Map<String, BigDecimal> outflow = new HashMap<>();
for (NormItem item : items) {
    outflow.merge(item.allocationKey() + "\n" + item.fromSourceId(), item.amount(), BigDecimal::add);
}
for (Map.Entry<String, BigDecimal> entry : outflow.entrySet()) {
    String[] parts = entry.getKey().split("\n");
    BigDecimal current = cellAmount(after, parts[0], parts[1]);
    BigDecimal used = cellAmount(consumed, parts[0], parts[1]);
    BigDecimal movable = current.subtract(used);
    if (entry.getValue().compareTo(movable) > 0) {
        throw ApiException.quotaExceeded("区块 " + parts[0] + " 在水源 " + parts[1]
                + " 可搬出额度 " + fmt(movable) + " 不足（已核销用水量不能搬走），需要 "
                + fmt(entry.getValue()));
    }
}
