                        versions(f.allocA(), vA, f.allocB(), vB)), null, 422);
        assertEquals("SOURCE_NOT_APPLICABLE", error(unknown).get("code").asText());

        // 适用性变化：预览时 s3 适用，重配移除 s3 后激活整单失败
        postOk("/api/windows/" + f.windowId() + "/rebalances/preview",
                previewBody(List.of(
